import{At as e,Pt as t,Ut as n,gt as r,ht as i,mt as a,n as o,pt as s,ut as c}from"./chunks/framework.BrKcMR_c.js";var l=JSON.parse(`{"title":"ADR-0019: Pens (projects) are folders you own","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/0019-pens-as-folders.md","filePath":"adrs/0019-pens-as-folders.md","lastUpdated":1789092097000}`),u={name:`adrs/0019-pens-as-folders.md`};function d(o,l,u,d,f,p){let m=t(`Term`);return e(),s(`div`,null,[l[5]||=a(`<h1 id="adr-0019-pens-projects-are-folders-you-own" tabindex="-1">ADR-0019: Pens (projects) are folders you own <a class="header-anchor" href="#adr-0019-pens-projects-are-folders-you-own" aria-label="Permalink to “ADR-0019: Pens (projects) are folders you own”">​</a></h1><p><strong>Status:</strong> Accepted · 2026-08-30</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>&quot;Projects&quot; grouped chats with a shared instruction blob, stored as a row in GRDB. It was thin: the instructions were invisible outside the app, there was no place for per-project agent guidance or referenced files, and the create UI was a bare form. Meanwhile memory already follows a principle that works: <em>a folder you own, in plain files</em> (ADR-0009). Projects should too.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2>`,5),c(`p`,null,[l[1]||=i(`Rename the concept to `,-1),c(`strong`,null,[r(m,{term:`pen`},{default:n(()=>[...l[0]||=[i(`Pens`,-1)]]),_:1})]),l[2]||=i(` (a pen is an enclosure for the herd) and store each as a folder under `,-1),l[3]||=c(`strong`,null,[c(`code`,null,`~/.goat/projects/<slug>/`)],-1),l[4]||=i(`:`,-1)]),l[6]||=a(`<div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-dimmed" style="--shiki-light:#24292e;--shiki-dark:#adbac7;--shiki-light-bg:#fff;--shiki-dark-bg:#22272e;" tabindex="0" dir="ltr"><code><span class="line"><span>~/.goat/projects/&lt;slug&gt;/</span></span>
<span class="line"><span>├── project.json   # PenSpec: id, name, emoji, OKLCH colour, createdAt, file refs</span></span>
<span class="line"><span>├── README.md      # the instructions: your brief</span></span>
<span class="line"><span>├── AGENTS.md      # the agent guide (references README); a GOATed coding template</span></span>
<span class="line"><span>└── CLAUDE.md      # one line → AGENTS.md</span></span></code></pre></div><ul><li><strong>Files are the source of truth.</strong> <code>PenStore</code> (GoatCore) reads/writes the folder; the app holds an observable <code>Pen</code>. GRDB keeps only the chat→pen link (the existing <code>chat.projectId</code> column, unrenamed to avoid a migration).</li><li><strong>AGENTS.md is the injected brief.</strong> A chat in a Pen gets the Pen&#39;s <code>AGENTS.md</code> in its system prompt (which points at README.md), so guidance is standard and hand-editable. AGENTS.md is scaffolded once from a coding-methodology template, then it&#39;s yours.</li><li><strong>Colour is OKLCH.</strong> Pens carry a perceptually-uniform <code>OKLCH</code> colour (custom picker; no native OKLCH exists), shown as the sidebar dot and the landing-page accent.</li><li><strong>Files are references, not copies.</strong> A Pen stores paths + security-scoped bookmarks. It points at your files, keeping Pens tiny.</li><li><strong>A landing page.</strong> Selecting a Pen shows its page (header, instructions editor, files, chats) instead of a chat.</li><li><strong>Migration.</strong> On first launch with old DB projects and no folders, they&#39;re copied into <code>~/.goat/projects</code> once; the DB rows are left in place, harmlessly.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><p>Pens are inspectable, portable, and editable outside GOAT, same ethos as memory. AGENTS.md/CLAUDE.md make each Pen a real agent workspace, aligned with the emerging <code>AGENTS.md</code> convention. The one wart: the DB column and a few internal helpers still say <code>project</code>, kept to avoid a schema migration for a cosmetic rename, noted, not load-bearing.</p><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to “Alternatives considered”">​</a></h2><p>Keep projects in GRDB (rejected: opaque, no room for agent guidance or files); one big <code>project.json</code> holding the prose too (rejected: prose wants to be real Markdown files you can open in any editor); copying referenced files into the Pen (rejected: bloats Pens, defeats &quot;small and optimised&quot;); native <code>ColorPicker</code> (rejected: sRGB, off-brand; see the OKLCH note).</p>`,6)])}var f=o(u,[[`render`,d]]);export{l as __pageData,f as default};